INSERT INTO items (id, subject_id, grade_level, question_text, question_type, option_a, option_b, option_c, option_d, option_e, correct_answer, difficulty, bloom_level, dok_level, irt_a, irt_b, irt_c, is_active, is_calibrated) VALUES
('a8000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 8, '√2 hansı ədəd növünə aiddir?', 'mcq', 'Natural', 'Tam', 'Rasional', 'İrrasional', NULL, 'D', 'asan', 'xatırlama', 1, 0.8, -1.5, 0.2, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 8, '2x + 5 = 13 tənliyinin həlli nədir?', 'mcq', '3', '4', '5', '6', NULL, 'B', 'asan', 'tətbiq', 2, 1.0, -1.0, 0.2, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000001', 8, '(a+b)² düsturu hansıdır?', 'mcq', 'a²+b²', 'a²+2ab+b²', 'a²-2ab+b²', '2a²+2b²', NULL, 'B', 'orta', 'xatırlama', 1, 1.2, 0.0, 0.2, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000001', 8, 'x²-9=0 tənliyinin kökləri cəmi nədir?', 'mcq', '-6', '0', '6', '9', NULL, 'B', 'orta', 'tətbiq', 2, 1.5, 0.5, 0.15, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000001', 8, 'f(x)=2x+1 funksiyasında f(3) neçədir?', 'mcq', '5', '6', '7', '8', NULL, 'C', 'asan', 'tətbiq', 2, 0.9, -0.8, 0.2, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000001', 8, 'Üçbucağın daxili bucaqları cəmi neçə dərəcədir?', 'mcq', '90', '180', '270', '360', NULL, 'B', 'çox_asan', 'xatırlama', 1, 0.7, -2.0, 0.25, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000001', 8, '3x² - 12 = 0 tənliyini həll edin və köklərin hasilini tapın.', 'mcq', '-4', '4', '-12', '12', NULL, 'A', 'çətin', 'analiz', 3, 1.8, 1.2, 0.1, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000001', 8, 'ABCD düzbucaqlısının diaqonalları O nöqtəsində kəsişir. AO=5 sm olarsa, BD neçə sm-dir?', 'mcq', '5', '10', '15', '20', NULL, 'B', 'çətin', 'analiz', 3, 1.6, 1.0, 0.15, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000001', 8, '5, 8, 3, 12, 7 ədədlərinin medianını tapın.', 'mcq', '5', '7', '8', '3', NULL, 'B', 'orta', 'tətbiq', 2, 1.1, 0.3, 0.2, TRUE, TRUE),
('a8000000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000001', 8, 'İsbat edin ki, hər hansı düzbucaqlının diaqonalları bərabərdir və bir-birini yarıya bölür.', 'essay', NULL, NULL, NULL, NULL, NULL, 'essay', 'çox_çətin', 'qiymətləndirmə', 4, 2.0, 2.0, 0.0, TRUE, FALSE);
